-- ============================================================================
-- BIBLE GAMES v2 — church-added questions + multiple game types
-- ============================================================================

-- Questions can now be global (church_id null, the shared seed pool) or
-- church-specific (added or AI-generated by that church's admin/pastor,
-- visible only to their own church — not leaked into other churches' pools).
alter table bible_quiz_questions add column church_id uuid references churches(id) on delete cascade;
alter table bible_quiz_questions add column created_by uuid references app_users(id);

create index idx_quiz_questions_church on bible_quiz_questions(church_id);

drop policy if exists bible_quiz_questions_select on bible_quiz_questions;
create policy bible_quiz_questions_select on bible_quiz_questions
  for select using (
    church_id is null  -- global pool, visible to everyone signed in
    or is_super_admin()
    or church_id = current_church_id()
  );

drop policy if exists bible_quiz_questions_write on bible_quiz_questions;
-- church_admin/pastor can add/edit/delete their OWN church's questions;
-- only super_admin can touch the global pool (church_id is null).
create policy bible_quiz_questions_insert on bible_quiz_questions
  for insert with check (
    is_super_admin()
    or (
      church_id = current_church_id()
      and created_by = auth.uid()
      and exists (select 1 from app_users where id = auth.uid() and role in ('church_admin', 'pastor'))
    )
  );

create policy bible_quiz_questions_update on bible_quiz_questions
  for update using (
    is_super_admin()
    or (church_id = current_church_id() and exists (select 1 from app_users where id = auth.uid() and role in ('church_admin', 'pastor')))
  );

create policy bible_quiz_questions_delete on bible_quiz_questions
  for delete using (
    is_super_admin()
    or (church_id = current_church_id() and exists (select 1 from app_users where id = auth.uid() and role in ('church_admin', 'pastor')))
  );

-- Generalize attempts to cover more than quiz — word search now, crossword
-- later. score/total_questions are reused generically as "points earned"
-- and "points possible" rather than renamed, to avoid a disruptive rename.
alter table bible_quiz_attempts add column game_type text not null default 'quiz'
  check (game_type in ('quiz', 'word_search'));

create index idx_quiz_attempts_game_type on bible_quiz_attempts(church_id, game_type);
